package com.sakti.banking.entity;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="service_requests") public class ServiceRequest { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private AppUser owner; @Enumerated(EnumType.STRING) private ServiceRequestType type; @Enumerated(EnumType.STRING) private ServiceRequestStatus status=ServiceRequestStatus.OPEN; @Column(length=500) private String details; private LocalDateTime createdAt; @PrePersist void create(){createdAt=LocalDateTime.now();}
 public Long getId(){return id;} public AppUser getOwner(){return owner;} public void setOwner(AppUser v){owner=v;} public ServiceRequestType getType(){return type;} public void setType(ServiceRequestType v){type=v;} public ServiceRequestStatus getStatus(){return status;} public void setStatus(ServiceRequestStatus v){status=v;} public String getDetails(){return details;} public void setDetails(String v){details=v;} public LocalDateTime getCreatedAt(){return createdAt;} }
